import{_ as a,c as i,o as t,a3 as s}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1787301752000}'),o={name:"guide/troubleshooting.md"};function n(l,e,r,h,p,d){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>This page collects common problems with ClipboxAI on macOS and how to resolve them.</p><h2 id="the-app-won-t-start-or-crashes-on-launch" tabindex="-1">The app won&#39;t start or crashes on launch <a class="header-anchor" href="#the-app-won-t-start-or-crashes-on-launch" aria-label="Permalink to &quot;The app won&#39;t start or crashes on launch&quot;">​</a></h2><ol><li>Make sure your macOS version meets the minimum (macOS 14 Sonoma+).</li><li>Quit and relaunch the app.</li><li>Reboot your Mac.</li><li><s>If downloaded from GitHub Releases, try the latest or notarized build.</s></li><li>If problems persist, collect logs (below) and open an issue.</li></ol><h2 id="clipboard-history-isn-t-capturing-copies" tabindex="-1">Clipboard history isn&#39;t capturing copies <a class="header-anchor" href="#clipboard-history-isn-t-capturing-copies" aria-label="Permalink to &quot;Clipboard history isn&#39;t capturing copies&quot;">​</a></h2><p>Symptoms: new copies don&#39;t appear in the history panel.</p><p>Checklist:</p><ol><li>Make sure the app is running and its menu bar icon is visible.</li><li>Confirm <strong>Clipboard monitoring</strong> is enabled in <strong>Settings → Privacy / General</strong>.</li><li>The app needs the relevant macOS permission to read the pasteboard in the background — see <a href="/guide/permissions.html">Permissions</a>.</li><li>Some apps (password managers, secure-input fields) intentionally block clipboard access; this is expected.</li></ol><h2 id="cloud-ai-actions-don-t-return-a-result" tabindex="-1">Cloud AI actions don&#39;t return a result <a class="header-anchor" href="#cloud-ai-actions-don-t-return-a-result" aria-label="Permalink to &quot;Cloud AI actions don&#39;t return a result&quot;">​</a></h2><p>Symptoms: an AI action fails, hangs, or shows a config error.</p><p>Checklist:</p><ol><li>Open <strong>Settings → AI</strong> and confirm a provider is selected and a key is entered.</li><li>Verify the key is valid for that provider and has quota/credits.</li><li>Check your network connection — cloud AI needs internet access.</li><li>Confirm the selected model name is correct for the provider.</li><li>If the config banner still appears in the AI Tool window, the key isn&#39;t saved to the Keychain; re-enter it.</li></ol><h2 id="marketplace-install-doesn-t-add-the-action" tabindex="-1">Marketplace install doesn&#39;t add the action <a class="header-anchor" href="#marketplace-install-doesn-t-add-the-action" aria-label="Permalink to &quot;Marketplace install doesn&#39;t add the action&quot;">​</a></h2><p>Symptoms: clicking <strong>Install</strong> does nothing, or the app doesn&#39;t open.</p><p>Checklist:</p><ol><li>The deep link <code>clipboxai://install?action=&lt;id&gt;</code> must be handled by the installed app — make sure ClipboxAI is installed and running.</li><li>If your browser blocks the deep link, copy it and open it manually, or install from inside the app&#39;s <strong>Marketplace</strong> tab.</li><li>Check that the action ID is still published in the marketplace.</li></ol><h2 id="resetting-the-app" tabindex="-1">Resetting the app <a class="header-anchor" href="#resetting-the-app" aria-label="Permalink to &quot;Resetting the app&quot;">​</a></h2><p>To reset settings and clear local data:</p><ol><li>Quit ClipboxAI.</li><li>Remove the container (this deletes history and settings):</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span></code></pre></div><ol start="3"><li>Reopen the app and reconfigure. API keys in the Keychain must be removed separately in <strong>Keychain Access</strong> if desired.</li></ol><h2 id="how-to-collect-debug-logs" tabindex="-1">How to collect debug logs <a class="header-anchor" href="#how-to-collect-debug-logs" aria-label="Permalink to &quot;How to collect debug logs&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copy logs to Desktop for sharing</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard/Data/Library/Logs/ClipboxAI/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span></code></pre></div><p>Then open an issue on <a href="https://github.com/clipboxAI" target="_blank" rel="noreferrer">GitHub</a> and attach the logs.</p><h2 id="report-an-issue" tabindex="-1">Report an issue <a class="header-anchor" href="#report-an-issue" aria-label="Permalink to &quot;Report an issue&quot;">​</a></h2><p>When opening an issue, include:</p><ul><li>macOS version (Apple menu → About This Mac)</li><li>ClipboxAI version (app menu → About)</li><li>Steps to reproduce</li><li>Logs (see above)</li></ul><p>This helps maintainers identify and fix the problem faster.</p>`,28)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
